Store each key’s latest value and expiration in a Map. A get returns null for a missing key or when time >= expiration, including zero-TTL entries.

```javascript
function solve(operations) {
  const cache = new Map();
  const results = [];

  for (const [time, type, key, value, ttl] of operations) {
    if (type === "put") {
      cache.set(key, { value, expiresAt: time + ttl });
    } else if (type === "get") {
      const entry = cache.get(key);
      if (entry === undefined) {
        results.push(null);
      } else if (time >= entry.expiresAt) {
        cache.delete(key);
        results.push(null);
      } else {
        results.push(entry.value);
      }
    }
  }

  return results;
