Track accepted events in the current fixed window, resetting the count when the window changes. Rejected events do not increment the count.

```javascript
function solve(times, limit, windowMs) {
  const results = [];
  let currentWindow = -1;
  let accepted = 0;

  for (const time of times) {
    const window = Math.floor(time / windowMs);

    if (window !== currentWindow) {
      currentWindow = window;
      accepted = 0;
    }

    const allowed = accepted < limit;
    results.push(allowed);
    if (allowed) accepted++;
  }

  return results;
}
```

